const LAUNCHERS: Record<string, { label: string; emoji: string; suffix: string; how: string }> = {
  modrinth: {
    label: "Modrinth App", emoji: "🟢", suffix: ".mrpack",
    how: "Double-clique sur le fichier `.mrpack`, ou dans Modrinth App : **+** → **Depuis un fichier**.",
  },
  curseforge: {
    label: "CurseForge", emoji: "🟠", suffix: "-CurseForge.zip",
    how: "Dans l'app CurseForge : **Créer un profil personnalisé** → **Importer**, puis choisis le fichier `.zip`.",
  },
  zip: {
    label: "Sans launcher", emoji: "📁", suffix: "-mods.zip",
    how: "Installe **NeoForge {neoforge}**, puis copie le dossier `mods` du zip dans ton dossier `.minecraft`. Le mode d'emploi est dans le zip.",
  },
};

const hex = (s: string) => new Uint8Array(s.match(/../g)!.map((b) => parseInt(b, 16)));
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
const clientMods = (rel: Release) => rel.mods.filter((m) => m.client !== "unsupported");

function panel(l: string, rel: Release, all: Release[]) {
  const L = LAUNCHERS[l] ?? LAUNCHERS.modrinth;
  const latest = rel.version === all[0].version;
  const mods = clientMods(rel);
  const mo = Math.round(mods.reduce((s, m) => s + m.size, 0) / 1048576);
  return {
    embeds: [{
      title: `${L.emoji} La Colonie ${rel.version} · ${L.label}`,
      color: 0xc9a227,
      description: L.how.replace("{neoforge}", rel.neoforge) +
        (latest ? "" : `\n\n⚠️ Ce n'est pas la dernière version : la plus récente est la **${all[0].version}**.`),
      fields: [
        { name: "Version", value: `${rel.version}${latest ? " · dernière" : ""}`, inline: true },
        { name: "Jeu", value: `Minecraft ${rel.minecraft} · NeoForge ${rel.neoforge}`, inline: true },
        { name: "Contenu", value: `${mods.length} mods${l === "modrinth" ? "" : ` · ${mo} Mo`}`, inline: true },
      ],
    }],
    components: [
      { type: 1, components: [{
        type: 3, custom_id: `mp:v:${l}`, placeholder: "Revenir à une autre version",
        options: all.slice(0, 25).map((r, i) => ({
          label: `${r.version}${i === 0 ? " · dernière" : ""}`, value: r.version,
          description: `${r.date} · ${r.notes}`.slice(0, 100), default: r.version === rel.version,
        })),
      }] },
      { type: 1, components: [
        { type: 2, style: 5, label: "Télécharger", emoji: { name: "⬇️" }, url: `${SELF}/download?l=${l}&v=${rel.version}` },
        { type: 2, style: 2, label: "Dernière version", emoji: { name: "⚡" }, custom_id: `mp:latest:${l}`, disabled: latest },
      ] },
    ],
  };
}

async function interaction(req: Request) {
  const body = await req.text();
  const sig = req.headers.get("x-signature-ed25519") ?? "", ts = req.headers.get("x-signature-timestamp") ?? "";
  const valid = sig.length === 128 &&
    nacl.sign.detached.verify(new TextEncoder().encode(ts + body), hex(sig), hex(DISCORD_KEY));
  if (!valid) return new Response("signature invalide", { status: 401 });
  const i = JSON.parse(body);
  if (i.type === 1) return json({ type: 1 }); // PING de vérification de Discord
  if (i.type === 3) {
    const all = RELEASES;
    const [, action, l] = String(i.data.custom_id).split(":");
    if (action === "launcher") return json({ type: 4, data: { ...panel(l, all[0], all), flags: 64 } }); // réponse privée
    if (action === "v") return json({ type: 7, data: panel(l, all.find((r) => r.version === i.data.values[0]) ?? all[0], all) });
    if (action === "latest") return json({ type: 7, data: panel(l, all[0], all) });
  }
  return json({ type: 4, data: { content: "Cette action n'est pas disponible.", flags: 64 } });
}

function readme(rel: Release) {
  const nf = rel.neoforge;
  return [
    `La Colonie ${rel.version} : installation sans launcher`,
    "",
    `1. Télécharge l'installateur NeoForge ${nf} :`,
    `   https://maven.neoforged.net/releases/net/neoforged/neoforge/${nf}/neoforge-${nf}-installer.jar`,
    "2. Lance-le (double-clic) et choisis « Install client ».",
    "3. Ouvre ton dossier .minecraft (Windows : Win+R, tape %appdata%\\.minecraft, puis Entrée).",
    "4. Copie-y le dossier « mods » de ce zip. S'il existe déjà, vide-le d'abord.",
    `5. Dans le launcher Minecraft, choisis le profil « neoforge-${nf} » et lance le jeu.`,
    "6. Adresse du serveur : lacolonie.mintservers.fr",
    "",
  ].join("\r\n");
}

function download(url: URL, all: Release[]) {
  const rel = all.find((r) => r.version === url.searchParams.get("v")) ?? all[0];
  const l = url.searchParams.get("l") ?? "";
  const launcher = LAUNCHERS[l] ? l : "modrinth";
  const mods = clientMods(rel);
  // ponytail: pas de contre-pression, le zip peut s'accumuler en mémoire si le client est lent ; à revoir au-delà de ~200 Mo.
  const stream = new ReadableStream<Uint8Array>({
    async start(ctrl) {
      const zip = new Zip((err, chunk, final) => {
        if (err) return ctrl.error(err);
        ctrl.enqueue(chunk);
        if (final) ctrl.close();
      });
      const add = (path: string, data: string | Uint8Array) => {
        const f = new ZipPassThrough(path);
        zip.add(f);
        f.push(typeof data === "string" ? strToU8(data) : data, true);
      };
      // Pas pour le zip « sans launcher » : servers.dat écraserait la liste de serveurs du joueur.
      if (launcher !== "zip") {
        for (const o of rel.overrides ?? []) add(`overrides/${o.path}`, octets(o.b64));
      }
      // Nos mods maison : dans overrides/mods pour les launchers, directement dans mods/ pour le zip.
      for (const e of rel.embarques ?? []) {
        if (FICHIERS[e.sha1]) add(`${launcher === "zip" ? "" : "overrides/"}mods/${e.file}`, octets(FICHIERS[e.sha1]));
      }
      if (launcher === "modrinth") {
        add("modrinth.index.json", JSON.stringify({
          formatVersion: 1, game: "minecraft", versionId: rel.version, name: "La Colonie",
          dependencies: { minecraft: rel.minecraft, neoforge: rel.neoforge },
          files: mods.map((m) => ({
            path: `mods/${m.file}`, hashes: { sha1: m.sha1, sha512: m.sha512 },
            env: { client: m.client, server: m.server }, downloads: [m.url], fileSize: m.size,
          })),
        }, null, 2));
      } else {
        if (launcher === "curseforge") {
          add("manifest.json", JSON.stringify({
            minecraft: { version: rel.minecraft, modLoaders: [{ id: `neoforge-${rel.neoforge}`, primary: true }] },
            manifestType: "minecraftModpack", manifestVersion: 1, name: "La Colonie", version: rel.version,
            author: "KOLRAX_MC", files: [], overrides: "overrides",
          }, null, 2));
        } else add("LISEZMOI.txt", readme(rel));
        const dir = launcher === "curseforge" ? "overrides/mods/" : "mods/";
        for (const m of mods) {
          const r = await fetch(m.url);
          if (!r.ok || !r.body) return ctrl.error(new Error(`${m.file} : ${r.status}`));
          const f = new ZipPassThrough(dir + m.file);
          zip.add(f);
          for await (const part of r.body) f.push(part);
          f.push(new Uint8Array(0), true);
        }
      }
      zip.end();
    },
  });
  return new Response(stream, {
    headers: {
      "content-type": launcher === "modrinth" ? "application/x-modrinth-modpack+zip" : "application/zip",
      "content-disposition": `attachment; filename="La-Colonie-${rel.version}${LAUNCHERS[launcher].suffix}"`,
    },
  });
}

Deno.serve(async (req) => {
  const url = new URL(req.url);
  try {
    if (req.method === "POST") return await interaction(req);
    if (url.pathname.endsWith("/download")) return download(url, RELEASES);
    return new Response("La Colonie : service de téléchargement du modpack.");
  } catch (e) {
    console.error(e);
    return new Response("Erreur temporaire, réessaie dans un instant.", { status: 500 });
  }
});
